'use strict';

// MODULES //

var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var values = require( '@stdlib/plot/vega/transform/label/methods' );


// MAIN //

/**
* Tests whether an input value is a supported label transform labeling method.
*
* @name isLabelTransformMethod
* @type {Function}
* @param {*} v - value to test
* @returns {boolean} boolean indicating whether an input value is a supported label transform labeling method
*
* @example
* var bool = isLabelTransformMethod( 'naive' );
* // returns true
*
* bool = isLabelTransformMethod( 'floodfill' );
* // returns true
*
* bool = isLabelTransformMethod( 'bar' );
* // returns false
*
* bool = isLabelTransformMethod( 'foo' );
* // returns false
*/
var isLabelTransformMethod = contains( values() );


// EXPORTS //

module.exports = isLabelTransformMethod;
